window.ATELIER_INDEX=[{"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s001"}, {"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "La finalul ședinței, puteți:", "u": "C13.html#p001"}, {"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "explica ce a moștenit spitalul românesc din modelul Semașko și de ce un număr mare de paturi era o problemă de eficiență, nu un avantaj de acoperire;", "u": "C13.html#l001"}, {"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "citi critic seriile de date despre paturi, durata de spitalizare și gradul de ocupare, cu sursa, setul de date și anul fiecărei valori, și recunoaște când două serii nu se pot alătura;", "u": "C13.html#l002"}, {"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "argumenta, pe datele reformei, dacă reducerea paturilor a fost o problemă de direcție sau de succesiune și în ce ordine ar fi trebuit făcute măsurile;", "u": "C13.html#l003"}, {"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "descrie mecanismele prin care numirea și evaluarea managerilor au legat spitalul de ciclul politic și ce au schimbat cadrul din Legea nr. 95/2006 și descentralizarea din 2010;", "u": "C13.html#l004"}, {"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "defini o rețea teritorială de spitale și explica ce costă absența ei, pe exemplul spitalelor regionale;", "u": "C13.html#l005"}, {"f": "Cursul 13", "t": "Obiectivele ședinței", "x": "analiza o decizie reală de politică spitalicească, reorganizarea unităților mici din 2011, după actul normativ, criteriile lui și ce s-a întâmplat după aceea.", "u": "C13.html#l006"}, {"f": "Cursul 13", "t": "Pregătirea pentru ședință", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s002"}, {"f": "Cursul 13", "t": "Pregătirea pentru ședință", "x": "Ședința pornește de la un document real: hotărârea Guvernului din 31 martie 2011 (HG nr. 345/2011) privind un grup de spitale mici . Înainte de ședință, citiți din ea raportul comisiei de selecție (anexa 1), cel puțin capitolul III, „Metodologie de selecție”: textul integral este liber pe Portalul Legislativ al Ministerului Justiției (legislatie.just.ro, HG nr. 345/2011). Notați în două rânduri ce criterii a folosit comisia și ce lipsește, după părerea dumneavoastră, dintre ele. Ce a hotărât efectiv Guvernul discutăm în sală.", "u": "C13.html#p002"}, {"f": "Cursul 13", "t": "Pregătirea pentru ședință", "x": "Ca lectură de context, parcurgeți secțiunea 4.1 („Physical resources”) din profilul sistemului de sănătate al României publicat de Observatorul European al Sistemelor și Politicilor de Sănătate în seria „Health Systems in Transition” (ediția din 2026, text integral liber în depozitul IRIS al Organizației Mondiale a Sănătății), partea despre infrastructura spitalicească. Dacă aveți timp, citiți din ediția din 2016 a aceluiași profil secțiunea 3.7.1 despre plata spitalelor prin grupele de diagnostice.", "u": "C13.html#p003"}, {"f": "Cursul 13", "t": "Pregătirea pentru ședință", "x": "Desfășurarea, pe scurt. Ședința durează trei ore, în sală, cu o pauză după prima jumătate. Urmăm decul titularului în ordinea lui: deschiderea cu documentul din 2011; supradimensionarea moștenită; reducerea paturilor; pauza; politizarea managementului; rețelele teritoriale absente; temele de după (finanțarea prin grupele de diagnostice, infrastructura, infecțiile asociate asistenței medicale, spitalele mici, spitalul universitar, chirurgia de zi, spitalele județene de urgență, acreditarea, personalul, spitalele regionale, comparațiile europene, pandemia, guvernanța); încheierea, cu un comitet cu roluri care reia decizia din 2011, și legătura cu tema următoare. La fiecare secțiune votați individual, pe telefon, o decizie luată din exemplele decului; rezultatul se proiectează o singură dată, după închiderea votului, și îl discutăm cu toată sala. Aveți nevoie de un telefon sau de un laptop cu acces la internet.", "u": "C13.html#p004"}, {"f": "Cursul 13", "t": "Pregătirea pentru ședință", "x": "Termenii folosiți cel mai des sunt trei: supradimensionarea (o capacitate de internare mai mare decât nevoia pe care o poate justifica modul de îngrijire existent), succesiunea reformei (ordinea în care se fac măsurile, nu numai conținutul lor) și rețeaua teritorială de spitale (spitale ierarhizate pe niveluri de competență, legate prin reguli de trimitere și de transfer). Restul vocabularului este explicat în aceste note.", "u": "C13.html#p005"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s003"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "În ultima zi a lunii martie 2011, Guvernul a adoptat o hotărâre cu un titlu lung și precis: aprobarea „Raportului comisiei de selecție a unităților sanitare cu paturi care nu pot încheia contracte cu casele de asigurări de sănătate, precum și a listei acestor unități sanitare” . Articolul operativ este scurt.", "u": "C13.html#p006"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "„(1) Se aprobă lista unităților sanitare cu paturi care nu pot încheia contracte cu casele de asigurări de sănătate, propusă de comisia de selecție menționată la art. 1, prevăzută în anexa nr. 2. (2) Prevederile alin. (1) se aplică începând cu data de 1 aprilie 2011.”", "u": "C13.html#p007"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Lista din anexa nr. 2 numără 67 de unități, grupate pe județe: spitale orășenești și comunale, spitale de boli cronice, centre de sănătate cu paturi . Citiți atent verbul. Hotărârea nu spune că spitalele se desființează; spune că nu mai pot încheia contracte cu casele de asigurări de sănătate. Pentru un spital mic, finanțat aproape în întregime din fondul de asigurări, efectul practic este oprirea activității spitalicești, dar decizia juridică de desființare sau de reorganizare rămâne a autorității care administrează spitalul. Aceasta este a doua jumătate a mecanismului: o hotărâre adoptată cu trei săptămâni înainte, HG nr. 212/2011, a aprobat un program național prin care autoritățile locale puteau înființa cămine pentru persoane vârstnice „prin reorganizarea unor unități sanitare cu paturi aflate în rețeaua proprie”, unități care se desființează în condițiile legii; în forma modificată prin HG nr. 1027/2013, programul finanțează cheltuielile curente ale căminelor cel mult 55 de luni, dintr-un buget total de 100 000 de mii de lei; pentru 2011, bugetul era de 55 000 de mii de lei .", "u": "C13.html#p008"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Raportul comisiei, publicat ca anexa 1 a hotărârii, spune de unde vine decizia. Comisia a fost constituită prin ordin al ministrului sănătății, după intrarea în vigoare a Ordonanței de urgență nr. 32/2011, iar procesul de reorganizare fusese demarat de la sfârșitul anului 2009 . Criteriile de selecție, de la a) la j), sunt criterii de capacitate și de acces: asigurarea serviciilor corespunzătoare structurii aprobate, continuitatea gărzilor cu personal de specialitate, clasificarea pe competență, distanța până la spitalele de nivel superior, încadrarea cu personal, accesul populației la urgența prespitalicească și la transport sanitar, accesul la serviciile de specialitate din județ, unicitatea unității la nivel județean sau zonal, starea fizică și juridică a clădirilor. Comisia a constatat că spitalele cu peste 130 de paturi îndeplinesc în majoritate aceste criterii, deci a analizat „cu precădere, unitățile sanitare care au sub 130 de paturi” . Pe lângă structură și personal, a privit complexitatea cazurilor (indicele de complexitate a cazurilor) și trei indicatori calitativi: reinternările în alt spital sau în același spital și transferurile în alt spital, pentru aceeași patologie, în 48 de ore . A avut în vedere și cum ar fi suplinită reorganizarea: prin asistență de urgență și transport medical și prin distanța până la cel mai apropiat spital de rang superior .", "u": "C13.html#p009"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Afirmație de verificat: „În 2011, Guvernul a desființat 67 de spitale.”", "u": "C13.html#p010"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Ce arată datele: hotărârea aprobă o listă de unități care nu pot încheia contracte cu casele de asigurări de sănătate, de la 1 aprilie 2011 ; înființarea căminelor prin desființarea unităților sanitare cu paturi o hotărăsc consiliile locale sau județene, în programul aprobat separat . Lista de 67 de poziții a programului căminelor, în forma consolidată, are 13 poziții abrogate, iar unitățile ei nu coincid integral cu cele 67 din lista casei de asigurări .", "u": "C13.html#p011"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Principiu general: o politică publică se citește în articolul ei operativ și în actele care îl pun în aplicare, nu în titlurile de presă; între „nu mai finanțăm” și „desființăm” stă o decizie a altei autorități, cu alt calendar.", "u": "C13.html#p012"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Decul pune patru întrebări, la care răspund secțiunile ședinței: ce a moștenit spitalul din modelul Semașko și de ce moștenirea era o problemă; de ce reducerea paturilor a fost corectă ca direcție și greșită ca succesiune; cum a transformat politizarea managementul spitalicesc într-un factor de eșec; ce este o rețea teritorială de spitale și de ce absența ei costă. Raportul comisiei din 2011 le formulează, în limbajul administrației, pe toate patru: sistemul moștenit era centralizat și „continuă să se bazeze pe asistența spitalicească ca principală metodă de intervenție” , capacitatea de internare era excedentară, managementul era legat de minister, iar ierarhia pe niveluri de competență era slabă.", "u": "C13.html#p013"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Reforma spitalicească a fost subiectul cel mai des invocat al politicii sanitare de după 1990 și unul dintre cele mai rar duse la capăt. Cronologia de mai jos păstrează reperele decului, corectate după sursele verificate.", "u": "C13.html#p014"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Moștenirea: un sistem de tip Semașko, cu decizie complet centralizată și fără separare între finanțator și prestator ; densitatea paturilor, după seria Eurostat, era de 892,18 la 100 000 de locuitori în 1990 .", "u": "C13.html#l012"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Prima reducere mare: în 1992, densitatea paturilor a coborât de la 7,9 la 6,8 la 1 000 de locuitori, prin tăierea paturilor din secțiile cu ocupare mică, mai ales maternități, după scăderea natalității care a urmat abolirii interzicerii avortului .", "u": "C13.html#l013"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Asigurările sociale de sănătate (sfârșitul anilor 1990): spitalele devin furnizori contractați de casele de asigurări; grupele de diagnostice (DRG) intră prin proiecte succesive între 1997 și 2002 și se aplică la nivel național în 2003 , cu raportarea electronică a cazurilor din 2006 .", "u": "C13.html#l014"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Legea nr. 95/2006, Titlul VII: managerul selectat prin concurs, comitetul director, consiliul medical .", "u": "C13.html#l015"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Descentralizarea din 2010: prin Ordonanța de urgență nr. 48/2010, 370 din 433 de spitale trec în administrarea consiliilor locale și județene .", "u": "C13.html#l016"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Reorganizarea spitalelor mici din 2011, cu lista de 67 de unități .", "u": "C13.html#l017"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Spitalele regionale: prevăzute într-o lege a spitalelor din 2004, neadoptată; trei dintre ele intră în Programul Operațional Regional 2014–2020, cu începerea construcției în 2019 .", "u": "C13.html#l018"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Prima decizie (vot individual), pe documentul proiectat: ce a hotărât efectiv Guvernul, la 31 martie 2011, pentru cele 67 de unități din listă ? (A) desființarea lor de la 1 aprilie 2011; (B) interdicția de a încheia contracte cu casele de asigurări de sănătate, de la 1 aprilie 2011; (C) transformarea lor directă în cămine pentru persoane vârstnice; (D) trecerea lor în administrarea consiliilor județene.", "u": "C13.html#p015"}, {"f": "Cursul 13", "t": "Deschiderea: documentul din 31 martie 2011", "x": "Răspunsul documentat este varianta B: articolul operativ aprobă lista unităților care „nu pot încheia contracte cu casele de asigurări de sănătate” și o aplică de la 1 aprilie 2011 . Varianta A confundă efectul economic cu actul juridic: desființarea, dacă a avut loc, a hotărât-o autoritatea care administra unitatea. Varianta C descrie un program separat, cel al căminelor, la care autoritățile locale puteau adera, nu o transformare dispusă de Guvern . Varianta D descrie descentralizarea din anul precedent, care trecuse deja majoritatea spitalelor la consiliile locale și județene . Diferența dintre B și A nu este o subtilitate juridică: ea explică de ce soarta unităților după 2011 a fost atât de diferită de la o localitate la alta, așa cum vom vedea la încheiere.", "u": "C13.html#p016"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s007"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Modelul Semașko, adoptat după război și moștenit după 1990, planifica serviciile prin normative de capacitate: paturi, posturi, clădiri la un număr de locuitori. Succesul se măsura în ceea ce intra în sistem, nu în ce producea acesta pentru sănătatea populației. Raportul comisiei din 2011 descrie aceeași moștenire ca sistem centralizat, bazat pe spital ca principală metodă de intervenție . Ediția din 2016 a profilului vede în supraoferta de îngrijiri spitalicești înalt specializate și în subutilizarea asistenței primare și comunitare, în parte, o moștenire a modelului Semașko, întreținută de o planificare slabă .", "u": "C13.html#p018"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Seria Eurostat a paturilor de spital, cea mai lungă serie comparabilă disponibilă azi, arată pentru România 892,18 paturi la 100 000 de locuitori în 1990, 687,29 în 2005, 665,47 în 2010 și 730,74 în 2024, ultimul an publicat; media Uniunii Europene (UE27) a fost de 573,54 în 2010 și de 507,35 în 2024 . Două observații contează. Prima: după 2010, densitatea paturilor nu a continuat să scadă în România, ci a crescut din nou, în timp ce media europeană a continuat să scadă . A doua: o serie se citește numai cu setul ei de date. Profilul sistemului de sănătate din 2026 are seria lui: 889 în 2000, 675 în 2011 și 728 în 2023, cu media UE27 de 469 în 2023, iar România apare pe locul al treilea în Uniune . Pentru România în 2023, cele două serii coincid practic (728,41 la Eurostat); în rest diferă: pentru 2000, Eurostat dă 769,31, iar profilul 889; media UE27 din 2023 este de 510,65 la Eurostat și de 469 în profil . Același profil dă, pentru 2022, 7,3 paturi la 1 000 de locuitori, față de media UE27 de 4,7 . Ediția din 2016 a profilului pornește de la 7,9 paturi la 1 000 de locuitori în 1990 și ajunge la 6,3 în 2013 . Diferențele vin din definiții (ce paturi se numără, ce unități), din revizuirile datelor și din populația de referință, nu din erori de tipar. De aceea, într-o analiză, nu se alătură valori din seturi diferite fără să se spună asta, iar fiecare cifră poartă sursa și anul ei.", "u": "C13.html#p019"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Decul compară România din 1989 cu media țărilor din Europa Occidentală și cu o „recomandare” a Organizației Mondiale a Sănătății privind numărul de paturi la 1 000 de locuitori. Aceste repere nu au, deocamdată, o sursă verificată pe disc și nu le folosim ca fapte (caseta „Ce nu putem afirma”). Raportul comisiei din 2011 folosea reperele experților Băncii Mondiale: 6,4 paturi la 1 000 de locuitori în România, față de aproximativ 5,86 în Uniunea Europeană . Concluzia rămâne valabilă și pe datele verificate: în 2024, România avea cu aproape jumătate mai multe paturi la 100 000 de locuitori decât media UE27 (730,74 față de 507,35) .", "u": "C13.html#p020"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Intuiția obișnuită spune că mai multe paturi înseamnă acces mai bun. Economia spitalului spune altceva. Un pat de spital poartă costuri fixe, adică personalul de gardă, încălzirea, energia, curățenia, întreținerea clădirii, indiferent dacă e ocupat sau nu. Când paturile sunt mai multe decât cazurile care le justifică, fie stau goale și costul pe caz crește, fie se umplu cu internări pe care un ambulatoriu bun le-ar fi evitat. Ambele variante consumă bani care lipsesc din alte niveluri ale sistemului.", "u": "C13.html#p021"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Al doilea mecanism este stimulentul. Un spital finanțat după capacitate, cu bugetul calculat după paturi și posturi, are interesul să-și păstreze paturile. Trecerea la plata pe caz prin grupele de diagnostice a schimbat stimulentul, dar a creat altele, pe care le discutăm la finanțare. Al treilea mecanism este durata de spitalizare. Ediția din 2016 a profilului arată că durata medie de spitalizare în toate spitalele a scăzut de la 11,4 zile în 1990 la 6,3 zile în 2013, cât media europeană de atunci (6,3), iar gradul de ocupare a paturilor a crescut de la 68% în 1990 la 84% în 2005 și a scăzut la 73% în 2013, puțin sub media europeană de 77% . Valorile decului pentru 1989 și 2006 (durate de peste două săptămâni, o ocupare de două treimi în 2005) nu se confirmă: în 2005, paturile erau ocupate în proporție mai mare, nu mai mică . Pe seria actuală a Eurostat, durata medie de spitalizare a României era de 7,0 zile în 2023, sub media UE27 de 7,96 zile din același an . Pe aceste date, durata medie a șederii nu mai pare problema principală. Datele disponibile indică mai degrabă volumul internărilor: profilul din 2026 dă pentru România 162 de externări la 1 000 de locuitori în 2022, față de 155 în media țărilor comparate . Raportul comisiei din 2011 numea deja rata de internare de 215,13 la 1 000 de locuitori din 2007 una dintre cele mai mari din Uniune .", "u": "C13.html#p022"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Al patrulea mecanism este infrastructura. Paturile multe se aflau în clădiri vechi. Ediția din 2016 a profilului constată că nu există informații oficiale despre starea clădirilor spitalelor publice, dar că majoritatea au fost construite în anii 1970 și 1980 și nu au fost bine întreținute . Reducerea paturilor fără reabilitarea clădirilor înseamnă mai puține paturi în clădiri la fel de deteriorate.", "u": "C13.html#p023"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "A doua decizie (vot individual): între 2010 și 2024, cum a evoluat densitatea paturilor de spital în România, după seria Eurostat, față de media UE27? (A) a continuat să scadă și a ajuns sub media UE27; (B) a scăzut și s-a apropiat de media UE27; (C) a crescut, în timp ce media UE27 a scăzut, deci distanța s-a mărit; (D) a rămas practic neschimbată, ca și media UE27.", "u": "C13.html#p024"}, {"f": "Cursul 13", "t": "Supradimensionarea moștenită", "x": "Răspunsul documentat este varianta C. Seria Eurostat dă pentru România 665,47 paturi la 100 000 de locuitori în 2010 și 730,74 în 2024, iar pentru media UE27 573,54 și, respectiv, 507,35 . Variantele A și B prelungesc tendința din anii 1990 și 2000, pe care o sugerează și decul, dar care s-a oprit în jurul anului 2011; profilul din 2026 descrie aceeași întoarcere, pe seria lui, de la 675 în 2011 la 728 în 2023 . Profilul nu dă o explicație unică a întoarcerii; două fapte documentate se potrivesc cu ea: deschiderea a 97 de spitale private mici în 2011 și creșterea numărului de spitale private după schimbarea plății pentru spitalizarea de zi din 2014 . Lecția pentru un rezident de sănătate publică este că o tendință se verifică pe ultimul an publicat, nu pe impresia lăsată de o reformă anunțată.", "u": "C13.html#p025"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s010"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "Reducerea paturilor a avut loc în valuri, nu continuu. Ediția din 2016 a profilului numește momentele: în 1992, densitatea a coborât de la 7,9 la 6,8 paturi la 1 000 de locuitori, în secțiile cu ocupare mică, mai ales maternități; în 2003 s-au închis 19 912 paturi, adică 12%; în 2010, încă 8 266, adică 6%; în 2011, odată cu închiderea celor 67 de spitale, încă 3% . Raportul comisiei din 2011 descrie valul din 2010: din februarie 2010, trei comisii conduse de secretari de stat au evaluat spitalele în teritoriu, iar măsurile luate au redus aproximativ 9 200 de paturi la nivel național, mai ales în secțiile ale căror servicii pot fi furnizate și în ambulatoriu, de exemplu dermatologie, oftalmologie, boli interne, diabet . Pasul următor era „Planul național de paturi”, care trebuia să reducă paturile aprobate pentru contractare cu casele de asigurări la 125 639 în 2012 . Ulterior, Planul național de paturi pentru 2014–2016, aprobat prin HG nr. 449/2014, a legat rambursarea serviciilor spitalicești de casa de asigurări de un număr total de paturi .", "u": "C13.html#p026"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "Seria paturilor din dec (valorile absolute pentru 1995, 2000, 2005 și 2010) nu se confirmă în sursele verificate și urcă și coboară fără o explicație; nu o folosim. Nici numărul spitalelor mici închise în anii 1990, pe care îl dă decul, nu are sursă; episodul documentat de închidere a spitalelor mici este cel din 2011, de la care a pornit ședința.", "u": "C13.html#p027"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "Reducerea era corectă ca direcție: sistemul avea mai multă capacitate de internare decât putea justifica un mod modern de îngrijire. Greșeala a fost de succesiune. Paturile au fost tăiate înainte ca pacientul să aibă unde merge în locul lor. Raportul comisiei din 2011 numea ambele componente. Invocând „unele studii”, pe care nu le numește, după care aproximativ 40% dintre cazurile internate s-ar fi putut trata în asistența de zi sau în ambulatoriu , el descria o strategie care „include raționalizarea infrastructurii spitalicești și măsuri pentru consolidarea sistemului de asistență ambulatorie”, cu reorganizarea spitalelor făcută „în paralel cu descentralizarea acestora” . Raportul nu spune în ce ordine trebuiau făcute cele două componente; ordinea, cu alternativa construită întâi, este teza acestei teme.", "u": "C13.html#p028"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "Alternativa avea cinci componente, pe care decul le enumeră: ambulatoriul de specialitate (tema precedentă), asistența medicală primară în mediul rural, spitalizarea de zi și chirurgia de zi, rețelele teritoriale, reabilitarea clădirilor. La una dintre ele, efectul unei schimbări de plată se vede în date: creșterea numărului de spitale private după 2014 a fost determinată în mare parte de schimbarea plății pentru chirurgia de zi și spitalizarea de zi din 2014 . Când plata există, oferta apare; când lipsește, pacientul rămâne cu singura poartă deschisă, internarea.", "u": "C13.html#p029"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "Decul adună în aceeași secțiune ineficiențele care țin de structură, nu de oameni. Durata medie de spitalizare și gradul de ocupare au fost discutate mai sus, pe valorile verificate. Reinternările sunt indicatorul continuității după externare. Comisia din 2011 a folosit chiar indicatori de acest tip, reinternările și transferurile pentru aceeași patologie în 48 de ore, ca semn al capacității unei unități de a-și rezolva cazurile . Investițiile de capital erau finanțate dintr-un buget separat al Ministerului Sănătății, nu din fondul de asigurări , deci un spital care economisea prin eficiență nu-și putea finanța din economie renovarea. Duplicarea investigațiilor, pacientul reinvestigat de la zero la fiecare internare, este un mecanism cunoscut al sistemelor fără dosar electronic și fără scrisoare medicală completă; ponderea din cheltuieli pe care o dă decul nu are însă sursă verificată.", "u": "C13.html#p030"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "A treia decizie (vot individual): sunteți într-una dintre cele trei comisii care, din februarie 2010, au evaluat spitalele în teritoriu; măsurile luate după evaluare au redus aproximativ 9 200 de paturi . Raportul din 2011 avea să citeze studii, nenumite, după care circa 40% dintre internări nu cereau spitalizare continuă și se puteau rezolva în spitalizarea de zi sau în ambulator . Ce trebuia să vină întâi? (A) reducerea liniară a paturilor în toate secțiile, ca să nu fie favorizat niciun spital; (B) plata și capacitatea pentru spitalizarea de zi și pentru ambulatoriu, apoi reducerea paturilor în secțiile ale căror cazuri trec acolo; (C) închiderea spitalelor cu gradul de ocupare cel mai mic, oricare ar fi distanța până la alt spital; (D) creșterea tarifului pe zi de spitalizare, ca spitalele să aibă resurse pentru modernizare.", "u": "C13.html#p031"}, {"f": "Cursul 13", "t": "Reducerea paturilor: corectă ca direcție, greșită ca succesiune", "x": "Răspunsul documentat este varianta B. Cifra pe care raportul o preia din studii nenumite este o estimare, nu o măsurătoare, dar sugerează o cerere care putea fi tratată altfel; problema era, deci, lipsa alternativei, nu numărul paturilor în sine . Când plata pentru chirurgia de zi și spitalizarea de zi s-a schimbat, în 2014, oferta a crescut repede, mai ales în sectorul privat . Varianta A tratează la fel secții cu nevoi diferite. Varianta C ignoră chiar criteriile comisiei din 2011, care au cerut să se ia în calcul distanța până la spitalul de nivel superior și accesul la urgența prespitalicească . Varianta D întărește stimulentul vechi, de a ține pacientul internat. Ordinea contează: o reducere care precedă alternativa mută pacientul, nu îl tratează.", "u": "C13.html#p032"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s014"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Înainte de 2010, spitalul public depindea de centru în aproape tot ce conta. Raportul comisiei din 2011 descrie cadrul: spitalele publice erau înființate și desființate prin hotărâre a Guvernului, la propunerea Ministerului Sănătății, care le aproba structura și numărul de paturi; comitetul consultativ, principalul organism de administrare, putea face doar recomandări directorilor, iar membrii lui erau confirmați de minister . Descentralizarea administrativă începuse abia în 2002, cu trecerea unor clădiri în domeniul public al autorităților locale , dar finanțarea locală a rămas nesemnificativă: ponderea bugetelor locale era de numai 1,2% din totalul cheltuielilor pentru sănătate, adică 236,3 milioane de lei din 19 702 milioane de lei .", "u": "C13.html#p033"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Mecanismul politizării, așa cum îl descrie decul, are patru consecințe. Instabilitatea: directorii se schimbă odată cu schimbarea politică, deci planificarea pe mai mulți ani devine imposibilă. Lipsa criteriilor de performanță: directorul nu este evaluat după calitatea îngrijirilor sau după rezultatele financiare, ci după relația cu cel care l-a numit. Achizițiile: favoritismul în contractele publice pentru echipamente și servicii. Personalul: numirile la conducerea secțiilor după loialitate. Decul ilustrează instabilitatea cu un număr de directori pe deceniu într-un spital județean și cu rapoarte ale instituțiilor anticorupție; aceste ilustrări nu au, în versiunea de față, o sursă verificată și rămân în caseta „Ce nu putem afirma”.", "u": "C13.html#p034"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Titlul VII al Legii nr. 95/2006 a pus cadrul unui management profesionist. Managerul spitalului public este selectat prin concurs sau licitație publică, trebuie să aibă pregătire medicală, economică sau juridică și formare specifică în managementul serviciilor de sănătate; conducerea executivă o asigură un comitet director format din manager, directorul medical, directorul financiar și, la spitalele cu peste 400 de paturi, directorul de îngrijiri; directorul medical conduce consiliul medical, alcătuit din șefii de secție și de laborator, farmacistul-șef și asistentul-șef . Decul dă pentru contractul de management două durate diferite, în două diapozitive. Forma în vigoare a legii (art. 176 alin. (4), modificat în 2025) prevede, pentru managerul care încheie contractul cu Ministerul Sănătății, cu ministerele sau instituțiile cu rețea sanitară proprie ori cu universitatea de medicină și farmacie, un contract de management „pe o perioadă de maximum 4 ani”, care poate înceta înainte de termen în urma evaluării anuale ; duratele din formele anterioare ale legii nu le-am verificat.", "u": "C13.html#p036"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Descentralizarea din 2010 a schimbat interlocutorul. Prin Ordonanța de urgență nr. 48/2010, 370 din 433 de spitale au trecut în administrarea consiliilor locale și județene, iar managerul încheie contractul de management cu conducerea administrației locale, nu cu ministrul sănătății . Ministerul urma să păstreze institutele naționale și clinice și o rețea de spitale clinice județene și municipale, pentru permanența la urgența de înaltă calificare ; profilul din 2026 numără 58 de spitale administrate de Ministerul Sănătății . Legătura dintre spital și ciclul politic nu a dispărut, s-a mutat: ciclul electoral al consiliului județean sau al primăriei înlocuiește ciclul guvernamental.", "u": "C13.html#p037"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Un exemplu documentat arată cum un indicator de performanță prost ales strică chiar informația pe care ar trebui să o producă. Ediția din 2016 a profilului explică subraportarea infecțiilor nosocomiale prin faptul că, în trecut, acestea au fost incluse în indicatorii individuali de performanță ai managerilor, care, în consecință, nu raportau toate cazurile . Penalitățile au fost eliminate ulterior, dar rata infecțiilor a rămas printre indicatorii după care este evaluat managerul, deci stimulentul de a nu raporta a rămas și el . Vom reveni la el la secțiunea despre infecții.", "u": "C13.html#p038"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Decul compară spitalul românesc cu modelul european: spitalul ca nod într-o rețea de îngrijiri coordonate, care tratează cazurile acute și complexe, urgențele grave și chirurgia, în mare parte în regim de zi, în timp ce bolile cronice stabile sunt îngrijite în ambulatoriu. Spitalul românesc făcea, în bună măsură, opusul: interna bolnavi cronici care puteau fi tratați ambulatoriu (hipertensiune arterială, diabet zaharat stabil, bronhopneumopatie obstructivă cronică ușoară), avea puțină chirurgie de zi și o unitate de primiri urgențe aglomerată de cazuri neurgente. Comparațiile numerice ale decului cu Regatul Unit și ponderea internărilor evitabile nu au sursă verificată; singurul reper de pe disc este estimarea pe care raportul din 2011 o preia din studii nenumite: aproximativ 40% dintre internări s-ar fi putut rezolva în asistența de zi sau în ambulatoriu .", "u": "C13.html#p039"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Consecința financiară este „piramida inversă”: banii merg spre vârf. Raportul comisiei din 2011 arată că sectorul spitalicesc consuma aproximativ 50% din fondul național unic de asigurări sociale de sănătate (49,8% în 2007, 48,1% în 2008 și 51,2% în 2009, după datele ministerului), la care se adăugau fondurile ministerului și ale autorităților locale, deci o cotă „cu mult peste media de 40% alocată pentru spitale în Uniunea Europeană” . Pentru pacientul cronic, spitalul era și varianta cea mai ieftină: internarea nu cerea plăți directe, în timp ce o parte din ambulatoriu le cerea. Ponderea asistenței medicale primare în fond, pe care o dă decul, nu a fost verificată.", "u": "C13.html#p040"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "A patra decizie (vot individual): după descentralizarea din 2010, managerul unui spital județean își pierde postul dacă nu își îndeplinește contractul de management. Cu cine a încheiat acest contract ? (A) cu ministrul sănătății; (B) cu conducerea administrației locale, adică a consiliului județean sau local; (C) cu casa județeană de asigurări de sănătate; (D) cu direcția de sănătate publică a județului.", "u": "C13.html#p041"}, {"f": "Cursul 13", "t": "Politizarea managementului spitalicesc", "x": "Răspunsul documentat este varianta B: Ordonanța de urgență nr. 48/2010 a prevăzut ca managerul să încheie contractul de management cu conducerea administrației locale, nu cu ministrul sănătății, cum se întâmpla înainte . Varianta A descrie situația de dinainte de 2010, valabilă azi numai pentru spitalele rămase la minister . Casa de asigurări (varianta C) cumpără servicii de la spital printr-un contract de furnizare, dar nu îl conduce, iar direcția de sănătate publică (varianta D) controlează și autorizează, fără să numească managerul. Întrebarea de discuție care urmează: dacă evaluarea managerului o face o autoritate aleasă pe patru ani, ce indicatori ar trebui să fie publici ca evaluarea să nu depindă de ciclul electoral?", "u": "C13.html#p042"}, {"f": "Cursul 13", "t": "Rețelele teritoriale absente", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s018"}, {"f": "Cursul 13", "t": "Rețelele teritoriale absente", "x": "O rețea teritorială de spitale înseamnă spitalele unei regiuni ierarhizate pe niveluri de competență, legate prin protocoale de trimitere și de transfer și cu un spital regional de referință pentru patologia complexă. Pacientul urcă sau coboară între niveluri după complexitatea cazului, iar plata stimulează folosirea corectă a fiecărui nivel. Decul descrie modelul european pe patru niveluri, de la spitalul local la centrul universitar, cu intervale de paturi pentru fiecare; intervalele nu au sursă verificată în această versiune, dar logica ierarhiei este cea a oricărui sistem planificat teritorial.", "u": "C13.html#p043"}, {"f": "Cursul 13", "t": "Rețelele teritoriale absente", "x": "În România, spitalele sunt clasificate pe categorii de competență de la I la V, după dotare și după specializarea personalului, categoria I fiind cea a serviciilor celor mai complexe . Clasificarea există; rețeaua, în sensul protocoalelor de transfer și al plății diferențiate pe niveluri, a rămas în mare parte pe hârtie. Fiecare județ are un spital județean de urgență care încearcă să rezolve aproape tot și trimite cazurile cele mai complexe spre centrele universitare, adesea după relații personale, nu după un protocol. Decul o spune într-o imagine: fiecare spital este o insulă.", "u": "C13.html#p044"}, {"f": "Cursul 13", "t": "Rețelele teritoriale absente", "x": "Profilul din 2026 rezumă istoria. Rapoarte de evaluare din 2003 încoace au cerut restructurarea serviciilor spitalicești, separarea nivelurilor de îngrijire și rețele regionale de spitale; Guvernul a aprobat Strategia națională de raționalizare a spitalelor în 2011; o lege a spitalelor din 2004, pe care Parlamentul nu a adoptat-o niciodată, prevedea construcția a opt spitale regionale noi; Programul Operațional Regional 2014–2020 a inclus trei dintre ele, cu începerea construcției în 2019; construcția celor trei spitale regionale de urgență, de la Iași, Cluj și Craiova, o coordonează Agenția Națională pentru Dezvoltarea Infrastructurii în Sănătate (ANDIS), înființată prin Planul Național de Redresare și Reziliență (PNRR); în 2016 au fost aprobate primele planuri regionale de sănătate . Decul atribuie spitalele regionale PNRR-ului; după sursa verificată, ele au intrat întâi în Programul Operațional Regional 2014–2020, iar PNRR a creat agenția care le coordonează . Stadiul lucrărilor în 2026 nu a fost verificat pentru această versiune.", "u": "C13.html#p045"}, {"f": "Cursul 13", "t": "Rețelele teritoriale absente", "x": "Titlul VII a fost cel mai ambițios cadru legislativ pentru spitale de după 1990. A prevăzut managerul profesionist și comitetul director , autorizarea sanitară de funcționare și acreditarea, iar spitalele sunt clasificate pe categorii de competență . Aplicarea a fost parțială. Concursul de manager s-a organizat, dar comisiile au rămas, după decul titularului, expuse influenței politice; rețelele teritoriale au rămas nefuncționale; finanțarea a rămas insuficientă. Datele decului despre înființarea autorității de acreditare și despre primele runde de acreditare nu au fost verificate pentru această versiune și se reiau, pe surse, în tema următoare, dedicată calității.", "u": "C13.html#p046"}, {"f": "Cursul 13", "t": "Rețelele teritoriale absente", "x": "A cincea decizie (vot individual): decul spune că spitalele regionale „nu au fost construite niciodată” și că ar fi un proiect al PNRR. În ce program de finanțare au fost incluse întâi, după profilul din 2026, cele trei spitale regionale de urgență de la Iași, Cluj și Craiova ? (A) în PNRR, după 2021; (B) în Programul Operațional Regional 2014–2020; (C) în legea spitalelor din 2004; (D) în bugetul fondului național unic de asigurări sociale de sănătate.", "u": "C13.html#p047"}, {"f": "Cursul 13", "t": "Rețelele teritoriale absente", "x": "Răspunsul documentat este varianta B: Programul Operațional Regional 2014–2020 a inclus trei dintre cele opt spitale prevăzute în 2004, cu începerea construcției, după profil, în 2019; PNRR a creat agenția care coordonează construcția . Stadiul real al lucrărilor nu l-am verificat. Varianta C este capcana cea mai instructivă: legea din 2004 prevedea opt spitale regionale, dar nu a fost adoptată . Varianta D este exclusă de modul de finanțare: investițiile de capital nu se fac din fondul de asigurări, ci dintr-un buget separat . Lecția pentru discuție: o rețea teritorială nu se construiește prin clădiri, ci prin reguli de trimitere, protocoale și plată pe niveluri; un spital regional fără protocoale de transfer devine încă o insulă, doar mai mare.", "u": "C13.html#p048"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s022"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Înainte de plata pe caz, spitalul primea un buget negociat anual, calculat după capacitate (paturi și personal). Grupele de diagnostice (DRG) clasifică pacienții internați în grupe omogene clinic și după resursele consumate, iar spitalul primește pentru fiecare caz un tarif ponderat după grupă. În România, ele au fost introduse prin proiecte succesive între 1997 și 2002, conduse de Institutul de Management al Serviciilor de Sănătate, cu sprijin american (USAID), pilotate în 10 spitale în 2001 și în 23 de spitale în 2002 și aplicate la nivel național, pentru cazurile acute continue, în 2003; s-a folosit inițial clasificarea americană, din octombrie 2005 cea australiană, iar în 2010 a fost creat sistemul românesc (RO-DRG) . Cronologia decului (pilot și generalizare în 2003) se confirmă astfel în substanță. Anul 2006, pe care îl dau rezumatele profilurilor, marchează o etapă ulterioară: din 2006, spitalele raportează electronic cazurile, odată cu sistemul DRG . Aplicarea națională a plății pe grupe de diagnostice rămâne, așadar, în 2003, cu etapa raportării electronice din 2006.", "u": "C13.html#p049"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Raportul comisiei din 2011 arată unde a rămas problema. Peste 70% din veniturile spitalelor veneau de la casa de asigurări, plătite prospectiv pe grupe de diagnostice, cu un tarif pe caz calculat pe datele sistemului australian, care nu acoperea costurile unor cazuri, mai ales ale celor complicate . Decul trage concluzia care decurge de aici: un sistem de plată pe caz funcționează dacă tariful reflectă costul real, dacă codificarea este corectă și dacă există audit sistematic; fără ele, apar supracodificarea (încadrarea cazului într-o grupă mai bine plătită), internările în plus și selecția cazurilor după rentabilitate. Deficitele cronice ale spitalelor, plătite prin transferuri suplimentare de la minister și de la autoritățile locale, sunt efectul combinat al unui fond insuficient, al costurilor fixe ale capacității excedentare și al ineficienței. Comparațiile europene ale decului (Germania, Franța) și citatele despre durata de adaptare a unui sistem de plată pe caz nu au fost verificate în textul surselor pentru această versiune.", "u": "C13.html#p050"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Clădirile spitalelor sunt, în cea mai mare parte, din anii 1970 și 1980, nu au fost bine întreținute, iar starea lor nu este raportată oficial . Decul adaugă echipamentele vechi, sterilizarea centrală deficitară, încălzirea și instalațiile electrice problematice și absorbția slabă a fondurilor europene după 2007; aceste constatări sunt plauzibile și concordă cu sursa, dar procentele decului (ponderea clădirilor construite într-o anumită perioadă, ponderea spitalelor „sub standard fizic” atribuită strategiei naționale de sănătate) nu se confirmă: profilul din 2016 spune chiar că informația oficială despre starea clădirilor lipsește .", "u": "C13.html#p051"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Infecțiile asociate asistenței medicale (numite tradițional nosocomiale) sunt unul dintre cei mai sensibili indicatori ai calității spitalului: depind de sterilizare, de aglomerare, de protocoalele de prevenire și de supraveghere. Pentru un rezident de epidemiologie sau de igienă, problema românească nu este numai frecvența lor, ci mai ales măsurarea: profilul din 2016 arată că sunt subraportate de spitale, mai ales pentru că au fost incluse în indicatorii individuali de performanță ai managerilor, care nu mai raportau toate cazurile; penalitățile au fost eliminate, dar indicatorul a rămas în evaluarea managerilor . Prevalențele pe care decul le atribuie studiilor europene de prevalență nu au fost verificate în textul acestor studii și nu le folosim ca fapte; tema se reia cu sursele ei în cursul despre calitate.", "u": "C13.html#p052"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "A șasea decizie (vot individual): sunteți în comisia care stabilește indicatorii de performanță ai managerilor de spital. Unul dintre membri propune „numărul de infecții asociate asistenței medicale raportate” ca indicator individual, cu penalizare pentru valori mari. Ce efect este cel mai probabil ? (A) scăderea reală a infecțiilor, prin presiunea pe manager; (B) subraportarea infecțiilor, deci pierderea informației de supraveghere; (C) niciun efect, pentru că raportarea este obligatorie; (D) creșterea raportării, pentru că managerii vor să arate transparență.", "u": "C13.html#p053"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Răspunsul documentat este varianta B. Exact acest mecanism explică, după profilul din 2016, subraportarea infecțiilor nosocomiale în România: incluse în indicatorii individuali de performanță ai managerilor, ele nu mai erau raportate integral, iar după eliminarea penalităților indicatorul a rămas în evaluarea managerilor, deci și stimulentul . Varianta A presupune că managerul controlează direct rata infecțiilor și că numărul raportat este numărul real; varianta C confundă obligația cu comportamentul; varianta D nu are sprijin în date. Principiul, valabil pentru orice sistem de supraveghere: un indicator care penalizează pe cel care raportează distruge raportarea. Indicatorii buni de calitate premiază supravegherea activă (de exemplu, numărul de culturi recoltate la cazurile suspecte) și se compară după ajustarea la risc.", "u": "C13.html#p054"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Decul pune față în față două logici. Logica economică: un spital mic are costuri fixe aproape la fel de mari ca unul mare, dar puține cazuri, deci un cost pe caz mai ridicat și, adesea, o experiență clinică insuficientă pentru cazurile grave. Logica politică: spitalul mic este semnul prezenței statului în comunitate, iar închiderea lui produce protest local, presiune pe minister și, de cele mai multe ori, un compromis. Concluzia decului este și concluzia ședinței: închiderea spitalelor mici poate fi justă ca politică publică numai dacă alternativa a fost creată întâi. Episodul din 2011 este testul acestei concluzii, la încheiere. Numerele decului despre spitalele mici din 1989 și despre numărul total de spitale în 1989, 2000 și 2015 nu se confirmă în sursele verificate; reperele documentate sunt 430 de spitale publice în rețeaua ministerului în 2008 și, pentru toate spitalele, 503 în 2010 și 464 în 2011 .", "u": "C13.html#p055"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Spitalul clinic universitar are o funcție dublă: îngrijire și formare a medicilor, la care se adaugă cercetarea. Șeful de secție este adesea și cadru didactic al universității de medicină, finanțarea vine din surse separate (casa de asigurări pentru îngrijiri, bugetul de stat pentru activitatea didactică și de cercetare), iar autoritatea se suprapune între conducerea universității și managerul spitalului. Concluzia decului privește direct rezidenții: calitatea formării depinde de calitatea îngrijirilor din spitalul în care se face, deci fragilitatea spitalului universitar este și fragilitatea formării medicale.", "u": "C13.html#p056"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Spitalul este una dintre cele mai complexe organizații: complexitate tehnică (proceduri, echipamente, specializări), umană (profesii și culturi profesionale diferite) și instituțională (ministerul, casa de asigurări, consiliul județean, universitatea, Colegiul Medicilor). Cadrul lui Donabedian deosebește structura (clădiri, personal, echipamente), procesul (ce se face și cum) și rezultatul (mortalitatea, complicațiile). Finanțarea românească a măsurat mult timp structura, prin paturi și personal contractat; procesul și rezultatul au rămas în urmă. Mortalitatea intraspitalicească ajustată după risc este indicatorul cel mai direct al calității clinice, iar decul subliniază că ea a fost mult timp necalculată standardizat și nepublicată; cifrele și proiectele europene de comparație pe care le citează decul se reiau, cu sursele lor, în tema următoare.", "u": "C13.html#p057"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Chirurgia de zi înseamnă intervenția și externarea în aceeași zi, cu riscuri infecțioase mai mici, revenire mai rapidă acasă și cost mai mic, iar pentru fond, paturi eliberate pentru cazurile complexe. În România, plata pe zi de spitalizare a descurajat-o, iar schimbarea plății pentru chirurgia de zi și spitalizarea de zi din 2014 a arătat cât de sensibilă este oferta la tarif . Ponderile decului pentru alte țări și pentru România nu au sursă verificată.", "u": "C13.html#p058"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Spitalul județean de urgență este veriga cea mai solicitată: unitatea de primiri urgențe, majoritatea specialităților, patologia complexă a unui județ întreg, cu transferurile spre centrele universitare făcute adesea fără protocol. Echipajele de urgență prespitalicească aduc pacientul până la el, după care el devine veriga critică. Personalul este partea cea mai fragilă: emigrarea medicilor și asistenților după 2007, mai ales în anestezie și terapie intensivă, neurochirurgie, ortopedie și cardiologie intervențională, lasă secții sub normativ și gărzi greu de acoperit. Cifrele decului despre paturile de terapie intensivă, populația deservită și densitatea medicilor nu au fost verificate pentru această versiune; exodul medical are o temă dedicată mai târziu în curs.", "u": "C13.html#p059"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Autorizarea sanitară de funcționare este condiția minimă, cu plan de conformare pentru unitățile care nu îndeplinesc normele, sub controlul direcției de sănătate publică. Acreditarea evaluează calitatea globală a spitalului după standarde (guvernanță, managementul riscului, siguranța pacientului, prevenirea infecțiilor). Decul apreciază acreditarea ca un progres real, dar încă insuficient de riguros; datele despre runde, proporții și acreditări internaționale se verifică și se discută în tema următoare.", "u": "C13.html#p060"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Agenda nerezolvată a temei, actualizată după datele verificate: spitalele regionale sunt în construcție, nu încheiate ; rețelele teritoriale și protocoalele de transfer rămân în mare parte informale; densitatea paturilor a crescut din nou după 2010 și rămâne mult peste media europeană ; durata medie de spitalizare a scăzut sub media UE27 , dar numărul externărilor rămâne mare ; supravegherea infecțiilor rămâne afectată de subraportare . Afirmația decului că durata medie de spitalizare ar fi „încă peste media UE” nu mai este valabilă pe datele actuale .", "u": "C13.html#p061"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Decul propune un spital județean construit, „spitalul județean X”, ca prototip al temei. Tabloul lui: un singur spital de nivel superior în județ, terapie intensivă sub normativ, specialiști plecați, deficit cronic acoperit de consiliul județean, acreditare la nivel minim, pacienți complecși transferați fără protocol la un centru universitar îndepărtat, infecții subraportate și un manager schimbat la fiecare schimbare politică. Cifrele lui sunt construite de autorul decului și nu descriu un spital real. Lectura lui este cea a întregii teme: niciun element al tabloului nu se rezolvă fără o intervenție la toate nivelurile sistemului.", "u": "C13.html#p062"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Decul compară reforma spitalicească românească cu cele din Estonia, Ungaria și Cehia și propune Estonia ca model de referință: reducerea capacității spitalicești făcută odată cu construirea ambulatoriului și cu dosarul electronic. Datele numerice ale acestor comparații nu au fost verificate pentru această versiune, dar logica lor este aceeași cu cea a secțiunii despre succesiune: voința politică, capacitatea instituțională și finanțarea, împreună. Evaluările externe ale sistemului românesc (profilurile Observatorului European, recomandările Comisiei Europene din semestrul european) au repetat, de-a lungul anilor, același diagnostic: prea mult spital, prea puțină asistență primară și ambulatorie. Raportul comisiei din 2011 îl formula și el, în aceiași termeni .", "u": "C13.html#p063"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Pandemia a pus la încercare toate verigile descrise în temă: paturile de terapie intensivă și personalul lor, transferurile între județe fără protocol, amânarea chirurgiei programate, stocurile de echipament de protecție. Cifrele decului despre paturile de terapie intensivă și despre valul al patrulea nu au fost verificate pentru această versiune; tema are un curs dedicat mai târziu.", "u": "C13.html#p064"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Achizițiile publice sunt zona cea mai expusă la corupție din spitale: echipamente supraevaluate, comisii de achiziții apropiate de anumiți furnizori, nereguli în proiectele cu fonduri europene. Decul susține că problema nu este una morală izolată, ci un simptom al guvernanței slabe: managementul numit politic facilitează corupția, iar remediul structural este autonomia managerială reală, însoțită de responsabilitate publică, audit și transparența achizițiilor. Rapoartele instituțiilor anticorupție pe care le invocă decul nu au fost verificate pentru această versiune.", "u": "C13.html#p065"}, {"f": "Cursul 13", "t": "Temele de după: spitalul văzut din mai multe unghiuri", "x": "Sinteza decului leagă tema de cele precedente: dezintegrarea circumscripției, subfinanțarea asistenței primare, un ambulatoriu fragmentat și un filtru slab trimit pacientul direct la spital și la unitatea de primiri urgențe. Exemplul decului este pacientul cu hipertensiune arterială: bine tratat de medicul de familie, nu face accident vascular cerebral și nu ocupă un pat de terapie intensivă. Comparația de cost pe care o dă decul nu are sursă verificată. Concluzia rămâne: spitalul românesc este suprasolicitat în primul rând pentru că nivelurile de dinaintea lui sunt prea slabe ca să-și facă treaba; politizarea, supradimensionarea și rețelele absente amplifică problema, dar nu o generează.", "u": "C13.html#p066"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s038"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Sursele cu text integral nu spun același lucru despre soarta celor 67 de unități , iar diferențele trebuie spuse cu sursa fiecăreia. Profilul din 2026 arată că închiderea a 67 de spitale publice în 2011 a redus temporar numărul total de spitale de la 503 în 2010 la 464 în 2011, că în același an s-au deschis 97 de spitale private mici și că mai mult de jumătate dintre spitalele închise s-au redeschis ulterior; scopul fusese transformarea paturilor de acuți, considerate prea multe, în paturi de îngrijiri de lungă durată . În alt capitol, același profil spune că inițiativa a eșuat: 36 dintre unitățile închise din cele 67 s-au redeschis ulterior și numai 20 au devenit cămine pentru vârstnici . Ediția din 2016 a profilului dă, la un an de la hotărâre, 21 de spitale transformate în cămine pentru vârstnici și 17 redeschise ca spitale sau centre de sănătate, cu multe altele redeschise în anii următori, după presiuni publice și politice . O relatare de presă din 9.10.2012, care cita reprezentanții Ministerului Sănătății, dădea alt tablou, la un an și jumătate după închidere: din cele 67 de spitale închise la 1 aprilie 2011, 21 funcționau ca cămine, 10 fuseseră redeschise ca spitale și 7 funcționau ca centre multifuncționale, iar 38 (56,7%) aveau utilitate publică . Aceeași relatare amintea că, în aprilie 2011, ministrul sănătății anunțase din reprofilarea celor 67 de unități o economie de 175 de milioane de lei la bugetul de stat ; economia efectivă nu a fost găsită într-o sursă oficială.", "u": "C13.html#p067"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Cifrele diferă pentru că descriu momente diferite (2012 față de un bilanț ulterior) și categorii diferite (cămine, spitale redeschise, centre multifuncționale). O a doua discrepanță ține chiar de documente: lista casei de asigurări (67 de unități) și lista programului căminelor (67 de poziții, din care 13 abrogate în forma consolidată) nu coincid integral . Comparate după denumiri, 14 unități din lista casei de asigurări nu apar printre pozițiile active ale listei căminelor, iar o unitate din Oțelul Roșu apare numai în aceasta din urmă . Cum se raportează o listă la cealaltă nu reiese din textele oficiale consultate.", "u": "C13.html#p068"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Comitetul reia decizia din 2011 pe un caz construit: Spitalul Orășenesc A, o unitate mică dintr-un județ construit, sub pragul de paturi pe care comisia l-a analizat cu precădere , aflată pe lista din martie. Criteriile, calendarul și programul căminelor sunt cele reale ; spitalul, orașul și oamenii sunt construiți. Fiecare participant primește prin cod QR una dintre cele șase fișe de mai jos, le citește în două minute și votează individual, din rolul primit, ce ar trebui să facă autoritatea care administrează spitalul.", "u": "C13.html#p069"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Conduceți Spitalul Orășenesc A de doi ani. Spitalul are medicină internă, pediatrie și o mică secție de chirurgie, gărzi acoperite greu, cu medici care fac naveta. Contractul cu casa de asigurări se încheie la sfârșitul lunii martie. Știți că indicele de complexitate a cazurilor e mic și că pacienții grav bolnavi sunt transferați la spitalul județean. Personalul, aproape o sută de oameni, vă întreabă ce se întâmplă cu posturile lor. Programul căminelor ar plăti cheltuielile curente ale unui cămin, pe o perioadă limitată. Ce cereți consiliului local: amânare, reorganizare sau o altă formă de îngrijire?", "u": "C13.html#p070"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Sunteți primarul orașului, ales acum trei ani, cu alegeri locale anul viitor. Spitalul este cel mai mare angajator public din oraș, iar consiliul local trebuie să decidă ce face cu clădirea. Programul guvernamental vă oferă bani pentru cheltuielile curente ale unui cămin pentru vârstnici, pe o perioadă limitată; după aceea, costul rămâne bugetului local, care contribuie acum foarte puțin la sănătate. Locuitorii vă spun că spitalul județean e prea departe iarna. Ce propuneți consiliului local și ce cereți în schimb de la minister și de la casa de asigurări?", "u": "C13.html#p071"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Reprezentați casa județeană de asigurări de sănătate. De la 1 aprilie nu mai puteți încheia contract de spitalizare cu Spitalul Orășenesc A, pentru că este pe lista aprobată de Guvern. Puteți însă contracta alte servicii, de exemplu ambulatoriu de specialitate, spitalizare de zi sau îngrijiri la domiciliu, dacă un furnizor autorizat le oferă. Fondul este limitat, iar spitalul județean cere și el mai mulți bani pentru cazurile transferate. Ce servicii sunteți dispus să contractați în oraș și în ce condiții?", "u": "C13.html#p072"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Reprezentați ministerul, a cărui comisie a propus lista și susține că sistemul are prea multe paturi de acuți și prea puține de îngrijiri de lungă durată. Criteriile comisiei au cuprins gărzile, personalul, distanța până la spitalul de nivel superior și accesul la urgența prespitalicească. Știți că urgența prespitalicească din zonă poate fi întărită, dar nu imediat. Presiunea bugetară cere economii anul acesta. Apărați decizia sau acceptați o amânare legată de condiții verificabile? Ce condiții?", "u": "C13.html#p073"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Sunteți medic de familie în oraș, cu o listă mare de pacienți vârstnici, mulți cu boli cronice. Trimiteți la Spitalul Orășenesc A pacienți pentru internări scurte, unele evitabile dacă ați avea acces rapid la analize și la consult de specialitate. Dacă spitalul închide, pacienții dumneavoastră vor merge la spitalul județean sau vor rămâne acasă. Ce ar trebui să existe în oraș, din prima zi, ca pacienții să nu rămână fără îngrijire?", "u": "C13.html#p074"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Aveți șaptezeci și doi de ani, insuficiență cardiacă și diabet, și locuiți singur într-un sat la marginea orașului. De două ori pe an ați fost internat la Spitalul Orășenesc A pentru decompensare. Nu aveți mașină; până la spitalul județean drumul durează mult, iar iarna e greu. Ați auzit că spitalul se transformă în cămin. Ce vă trebuie ca să fiți îngrijit fără să plecați din comunitate?", "u": "C13.html#p075"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "A șaptea decizie (vot individual, din rolul primit): ce ar trebui să hotărască autoritatea care administrează Spitalul Orășenesc A, aflat pe lista aplicată de la 1 aprilie 2011 ? (A) aplicarea întocmai a hotărârii: încetarea spitalizării continue de la 1 aprilie și transformarea în cămin, prin programul guvernamental; (B) încetarea spitalizării continue numai după ce sunt funcționale alternativele: urgența prespitalicească și transportul sanitar, ambulatoriul și spitalizarea de zi contractate cu casa de asigurări, paturi de îngrijiri de lungă durată cu finanțare asigurată după încheierea programului; (C) menținerea spitalului ca atare, cu finanțare integrală din bugetul local; (D) contestarea hotărârii în instanță și menținerea activității până la o decizie definitivă.", "u": "C13.html#p076"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Rezultatul se discută întâi pe roluri: ce a votat managerul, ce a votat primarul, ce a votat pacientul. Varianta susținută de note este B, iar argumentele vin din trei locuri. Primul este chiar raportul comisiei: criteriile au cerut să se țină seama de accesul la urgența prespitalicească și la transport sanitar și de distanța până la spitalul de nivel superior, iar comisia a analizat cum ar fi suplinită reorganizarea ; varianta B transformă aceste criterii în condiții de aplicare. Al doilea este secțiunea despre succesiune: după studiile, nenumite, citate de raport, circa 40% dintre cazuri nu cereau internare continuă , dar numai dacă această asistență exista. Al treilea este ce s-a întâmplat după 2011: inițiativa a eșuat ca transformare în îngrijiri de lungă durată, cu 36 de unități redeschise ulterior și numai 20 de cămine pentru vârstnici, după profilul din 2026 . Varianta A repetă greșeala de succesiune, iar finanțarea programului căminelor era limitată în timp . Varianta C mută costul pe un buget local care contribuia foarte puțin la sănătate și păstrează capacitatea pe care toate evaluările o considerau excedentară. Varianta D a fost aleasă de unele comunități; relatarea de presă din 2012 menționează puține unități rămase în funcțiune prin decizii ale instanței , dar litigiul amână decizia, nu o înlocuiește.", "u": "C13.html#p077"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Spitalul românesc a moștenit un model în care capacitatea, adică paturile, era măsura succesului; o capacitate pe care nu o justifică nevoia costă și când nu e folosită.", "u": "C13.html#l007"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Direcția reducerii paturilor a fost corectă; succesiunea a fost greșită, pentru că alternativa (ambulatoriul, spitalizarea de zi, îngrijirile de lungă durată) nu a fost construită înainte.", "u": "C13.html#l008"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Numirea și evaluarea managerilor au legat spitalul de ciclul politic; descentralizarea din 2010 a mutat legătura de la minister la autoritățile locale, fără să o desfacă.", "u": "C13.html#l009"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Fără niveluri de competență funcționale și fără reguli de transfer, fiecare spital lucrează ca o insulă, iar cazurile complexe circulă după relații, nu după protocol.", "u": "C13.html#l010"}, {"f": "Cursul 13", "t": "Încheierea: comitetul pe decizia din 2011", "x": "Decizia din 2011 nu a desființat spitale prin hotărârea Guvernului: le-a scos din contractarea cu casele de asigurări; ce a urmat arată de ce alternativa trebuie să existe înainte de retragerea finanțării.", "u": "C13.html#l011"}, {"f": "Cursul 13", "t": "Firul narativ: de la structură la calitate", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s047"}, {"f": "Cursul 13", "t": "Firul narativ: de la structură la calitate", "x": "Tema aceasta a analizat structura spitalului: capacitatea moștenită, succesiunea reformelor, politizarea managementului, rețelele absente. Tema următoare, „Spitalul românesc II”, intră în interiorul spitalului: calitatea îngrijirilor, cum se măsoară și ce a adus acreditarea, folosind cadrul lui Donabedian (structură, proces, rezultat). Legăturile sunt directe. Supradimensionarea și presiunea de a interna afectează calitatea. Managementul legat de ciclul politic blochează aplicarea protocoalelor de calitate. Infecțiile asociate asistenței medicale cer supraveghere activă și indicatori care nu penalizează raportarea . Codificarea corectă a cazurilor este condiția atât a calității, cât și a unei plăți corecte prin grupele de diagnostice . Rămân deschise, pentru temele de mai târziu, spitalele regionale și planificarea, finanțarea și starea actuală a sistemului.", "u": "C13.html#p078"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "u": "C13.html#s048"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "De ce numărul mare de paturi moștenit era o problemă de eficiență, nu un avantaj de acoperire? Folosiți seria Eurostat și spuneți de ce nu o alăturați fără mențiune valorilor din profilul sistemului de sănătate.", "u": "C13.html#l019"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "De ce reducerea paturilor a fost corectă ca direcție, dar greșită ca succesiune? Sprijiniți-vă pe raportul comisiei din 2011.", "u": "C13.html#l020"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Ce s-a întâmplat cu durata medie de spitalizare și cu gradul de ocupare a paturilor între 1990 și 2013 și cum se compară România azi cu media UE27?", "u": "C13.html#l021"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Prin ce mecanisme leagă numirea și evaluarea managerului spitalul de ciclul politic? Ce a schimbat descentralizarea din 2010?", "u": "C13.html#l022"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Ce a prevăzut Titlul VII al Legii nr. 95/2006 pentru conducerea spitalului și ce a rămas neaplicat?", "u": "C13.html#l023"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Ce este o rețea teritorială de spitale și de ce clasificarea pe categorii de competență nu este suficientă pentru ca rețeaua să funcționeze?", "u": "C13.html#l024"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "De ce un indicator de performanță al managerului bazat pe infecțiile raportate produce subraportare?", "u": "C13.html#l025"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "De ce sistemul românesc de plată pe caz nu a produs eficiența așteptată? Folosiți observațiile raportului comisiei din 2011 despre tarif.", "u": "C13.html#l026"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Ce a hotărât, juridic, Guvernul la sfârșitul lui martie 2011 și de ce efectele au diferit de la o localitate la alta?", "u": "C13.html#l027"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "De ce spitalul nu poate fi reformat separat de asistența medicală primară și de ambulatoriu?", "u": "C13.html#l028"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Valorile pentru 1989 din dec (numărul de paturi, numărul de spitale și densitatea paturilor la 1 000 de locuitori, atribuite unei lucrări de istorie a sănătății publice) nu au fost verificate: lucrarea nu este pe disc. Seriile verificate încep în 1990 și dau valori diferite între ele (Eurostat și ediția din 2016 a profilului) .", "u": "C13.html#l029"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Media țărilor din Europa Occidentală din dec și „recomandarea” Organizației Mondiale a Sănătății privind numărul de paturi la 1 000 de locuitori nu au o sursă verificată; nu le folosim.", "u": "C13.html#l030"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Seria absolută a paturilor din dec pentru anii 1995–2010 și numărul spitalelor mici închise în anii 1990 nu se confirmă; numărul spitalelor din dec pentru 1989, 2000 și 2015 nu se confirmă.", "u": "C13.html#l031"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Durata medie de spitalizare și gradul de ocupare din dec pentru 1989, 2005 și 2006 sunt contrazise de profilul din 2016 .", "u": "C13.html#l032"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Citatele în limba engleză atribuite în dec unor autori (despre reforma anunțată de mai multe ori, despre ingerința politică, despre succesiune) nu au fost găsite în textele verificate; nu le folosim ca citate.", "u": "C13.html#l033"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Numărul de directori pe deceniu într-un spital județean, durata contractului de management în formele Legii nr. 95/2006 anterioare celei în vigoare, datele despre înființarea autorității de acreditare și despre primele runde de acreditare, prevalențele infecțiilor asociate asistenței medicale atribuite studiilor europene, ponderea spitalelor „sub standard fizic”, ponderea asistenței medicale primare în fond, densitatea medicilor, paturile de terapie intensivă din timpul pandemiei și comparațiile cu alte țări nu au fost verificate pentru această versiune a notelor.", "u": "C13.html#l034"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Lucrarea primară despre urmările închiderii celor 67 de unități (Scîntee și colaboratorii, 2018), citată de profilul din 2026, nu a fost consultată direct; cifrele ei le cităm prin profil . Ordinul ministrului sănătății care a constituit comisia și a aprobat criteriile, hotărârile judecătorești de redeschidere și starea actuală a unităților din listă nu au fost găsite în sursele oficiale consultate.", "u": "C13.html#l035"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Listele celor două hotărâri din 2011 nu coincid, iar raportul dintre ele nu a putut fi stabilit din textele consultate . Economia bugetară anunțată în aprilie 2011 este o declarație relatată de presă, nu un rezultat verificat .", "u": "C13.html#l036"}, {"f": "Cursul 13", "t": "Întrebări de autoevaluare", "x": "Cifra de aproximativ 40% a raportului comisiei din 2011 vine din „unele studii” pe care raportul nu le numește; nu le-am găsit și o folosim ca estimare atribuită raportului, nu ca măsurătoare .", "u": "C13.html#l037"}, {"f": "Surse", "t": "Vlădescu C, Scîntee SG, Hernández-Quevedo C, Tille F, Eriksen A. Romania: Health System Review. Health Systems in Transition. 2026;28(1). Copenhaga: European Observatory on Health Systems and Policies; 2026.", "x": "", "u": "surse.html#S001"}, {"f": "Surse", "t": "Vlădescu C, Scîntee SG, Olsavszky V, Hernández-Quevedo C, Sagan A. Romania: health system review. Health Systems in Transition. 2016;18(4):1–170. PMID 27603897", "x": "", "u": "surse.html#S002"}, {"f": "Surse", "t": "HG nr. 345/2011, M. Of. nr. 226 din 31.03.2011", "x": "", "u": "surse.html#S003"}, {"f": "Surse", "t": "HG nr. 212/2011, M. Of. nr. 175 din 11.03.2011", "x": "", "u": "surse.html#S004"}, {"f": "Surse", "t": "Eurostat. Hospital beds by function and type of care (hlth_rs_bds1), actualizat 13.07.2026; unit=P_HTHAB, facility=HBEDT.", "x": "", "u": "surse.html#S005"}, {"f": "Surse", "t": "Eurostat. In-patients average length of stay in hospitals (hlth_talos1), actualizat 12.03.2026; icd10=TOTAL, sex=T, age=TOTAL.", "x": "", "u": "surse.html#S006"}, {"f": "Surse", "t": "Gândul (preluare Mediafax). Doar puțin peste jumătate dintre spitalele închise pentru reorganizare au utilitate publică. 9.10.2012.", "x": "", "u": "surse.html#S007"}, {"f": "Surse", "t": "Legea nr. 95/2006 privind reforma în domeniul sănătății, republicată, forma consolidată pe Portalul legislativ (ultima consolidare afișată: 08.08.2026).", "x": "", "u": "surse.html#S008"}, {"f": "Surse", "t": "Legea nr. 185/2017 privind asigurarea calității în sistemul de sănătate (forma consolidată)", "x": "", "u": "surse.html#S009"}, {"f": "Surse", "t": "Ordinul președintelui ANMCS nr. 10/2018 privind aprobarea categoriilor de acreditare a unităților sanitare cu paturi, ciclul al II-lea", "x": "", "u": "surse.html#S010"}, {"f": "Surse", "t": "HG nr. 521/2023, pachetele de servicii și Contractul-cadru (forma actualizată, ianuarie 2026)", "x": "", "u": "surse.html#S011"}, {"f": "Surse", "t": "Lista actualizată a spitalelor încadrate în categorii de acreditare, ciclul al II-lea, 30 martie 2026", "x": "", "u": "surse.html#S012"}, {"f": "Surse", "t": "Raport de activitate ANMCS 2025 (aprobat prin Ordinul președintelui ANMCS nr. 36/31.03.2026)", "x": "", "u": "surse.html#S013"}, {"f": "Surse", "t": "Studiul de prevalență de moment al IAAM și al consumului de antimicrobiene în spitalele din România, raport național 2023", "x": "", "u": "surse.html#S014"}, {"f": "Surse", "t": "Analiza focarelor de IAAM pentru anul 2025", "x": "", "u": "surse.html#S015"}, {"f": "Surse", "t": "Legea nr. 46/2003 a drepturilor pacientului (forma consolidată)", "x": "", "u": "surse.html#S016"}, {"f": "Surse", "t": "The impact of hospital accreditation on the quality of healthcare: a systematic literature review", "x": "", "u": "surse.html#S017"}, {"f": "Surse", "t": "Ordinul MS nr. 1101/2016 (Norme de supraveghere, prevenire și limitare a IAAM)", "x": "", "u": "surse.html#S018"}, {"f": "Cursul 13", "t": "Spitalul românesc I: supradimensionarea moștenită, eșecul reformelor structurale, politizarea managementului, rețelele teritoriale absente", "x": "săptămână 7", "u": "C13.html"}, {"f": "Cursul 14", "t": "Spitalul românesc II: acreditarea între promisiune și paradox", "x": "săptămână 8 · în elaborare", "u": "index.html#M5"}];
